import DOMPurify from "dompurify";
import { marked } from "marked";
import { useEffect, useMemo, useState, type FormEvent, type ReactNode } from "react";
import type { ToolNestModuleRouteRenderProps } from "@toolnest/react-module-sdk";
import { RiAddLine, RiArrowLeftLine, RiBarChartLine, RiCalendarLine, RiDeleteBinLine, RiEditLine, RiExternalLinkLine, RiFileTextLine, RiFlagLine, RiGitBranchLine, RiInformationLine, RiLinkM, RiMore2Line, RiRefreshLine, RiSaveLine, RiSearchLine, RiServerLine, RiSettings3Line, RiTimeLine } from "@remixicon/react";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from "@/components/ui/alert-dialog";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Empty, EmptyDescription, EmptyHeader, EmptyTitle } from "@/components/ui/empty";
import { Field, FieldDescription, FieldGroup, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Select, SelectContent, SelectGroup, SelectItem, SelectLabel, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Textarea } from "@/components/ui/textarea";

import type { Milestone, Project, RelatedResource, Ticket, TimelineEvent, WorkflowApi } from "../api";

type PageProps = ToolNestModuleRouteRenderProps & { api: WorkflowApi };
type Router = PageProps["router"];
type MilestoneDraft = { name: string; goal: string; target_at: string; status: string; completion_criteria: string; risk_note: string; review_markdown: string; progress_mode: string; manual_progress: string; owner_name: string };
type ResourceDraft = { name: string; resource_type: string; identifier: string; external_url: string; description: string; protocol: string; port: string; provider: string; branch: string; document_type: string; ticket_ids: string[]; milestone_ids: string[] };

const projectStatuses = [{ value: "planning", label: "规划中" }, { value: "active", label: "进行中" }, { value: "paused", label: "已暂停" }, { value: "completed", label: "已完成" }];
const milestoneStatuses = [{ value: "pending", label: "计划中" }, { value: "in_progress", label: "进行中" }, { value: "completed", label: "已完成" }, { value: "cancelled", label: "已取消" }];
const milestoneModes = [{ value: "ticket_count", label: "按工单数量" }, { value: "manual", label: "手动设置" }];
const resourceTypes = [{ value: "server", label: "服务器" }, { value: "repository", label: "代码仓库" }, { value: "document", label: "文档" }, { value: "custom", label: "自定义" }];
const timelineLabels: Record<string, string> = { project_risk: "项目风险", milestone_due: "里程碑到期", resource_created: "资源已创建", ticket_created: "工单已创建", ticket_updated: "工单已更新", ticket_completed: "工单已完成", ticket_reopened: "工单已重新打开", ticket_cancelled: "工单已终止", node_completed: "节点已完成", node_blocked: "节点已阻塞" };
const statusLabels: Record<string, string> = { planning: "规划中", active: "进行中", paused: "已暂停", completed: "已完成", archived: "已归档", pending: "计划中", planned: "计划中", in_progress: "进行中", cancelled: "已取消", blocked: "阻塞", draft: "草稿", ready: "待执行", normal: "正常", risk: "有风险", overdue: "已逾期" };

function errorMessage(error: unknown, fallback: string) { return error instanceof Error ? error.message : fallback; }
function requiredParam(value: string | undefined, label: string) { if (!value) throw new Error(label + "参数缺失。"); return value; }
function formatDate(value?: string | null) { return value ? new Intl.DateTimeFormat("zh-CN", { dateStyle: "medium" }).format(new Date(value)) : "未设置"; }
function formatDateTime(value?: string | null) { return value ? new Intl.DateTimeFormat("zh-CN", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "未记录"; }
function dateInput(value?: string | null) { return value ? new Date(value).toISOString().slice(0, 10) : ""; }
function toIso(value: string) { return value ? new Date(value).toISOString() : null; }
function normalizeMilestoneStatus(value: string) { return value === "planned" ? "pending" : value === "active" ? "in_progress" : value; }
function statusVariant(value: string): "default" | "secondary" | "outline" | "destructive" { return ["completed", "active", "normal"].includes(value) ? "default" : ["blocked", "cancelled", "overdue", "risk"].includes(value) ? "destructive" : ["planning", "pending", "in_progress", "planned"].includes(value) ? "outline" : "secondary"; }
function StatusBadge({ value }: { value: string }) { return <Badge variant={statusVariant(value)}>{statusLabels[value] ?? (value || "未知")}</Badge>; }
function HealthBadge({ value }: { value: string }) { return <Badge variant={statusVariant(value)}>{({ normal: "状态正常", risk: "存在风险", overdue: "已逾期" } as Record<string, string>)[value] ?? statusLabels[value] ?? "状态未知"}</Badge>; }
function EmptyState({ description, action }: { description: string; action?: ReactNode }) { return <Empty><EmptyHeader><EmptyTitle>暂无数据</EmptyTitle><EmptyDescription>{description}</EmptyDescription></EmptyHeader>{action ? <div className="flex justify-center">{action}</div> : null}</Empty>; }
function LoadingState() { return <div className="grid gap-3 rounded-lg border border-dashed p-6" aria-label="正在加载"><Skeleton className="h-5 w-2/5" /><Skeleton className="h-24 w-full" /><Skeleton className="h-24 w-full" /></div>; }
function ErrorState({ message, retry }: { message: string; retry?: () => void }) { return <Alert variant="destructive"><AlertTitle>加载失败</AlertTitle><AlertDescription className="flex flex-wrap items-center gap-3">{message}{retry ? <Button size="sm" variant="outline" onClick={retry}><RiRefreshLine data-icon="inline-start" />重试</Button> : null}</AlertDescription></Alert>; }
function ProjectFrame({ children }: { children: ReactNode }) { return <section className="tn-workflow-tickets-project-page grid gap-5">{children}</section>; }
function countEntries(value: unknown) { return value && typeof value === "object" ? Object.entries(value as Record<string, unknown>).map(([key, item]) => [key, Number(item) || 0] as const) : []; }
function markdownHtml(value: string) { return { __html: DOMPurify.sanitize(String(marked.parse(value || "还没有记录。", { breaks: true, gfm: true }))) }; }
function ticketProgress(ticket: Ticket) { const total = ticket.node_instances.length || 1; return Math.round(ticket.node_instances.filter((node) => node.status === "completed").length / total * 100); }
function currentTicketNode(ticket: Ticket) { return ticket.node_instances.find((node) => ["ready", "in_progress", "blocked"].includes(node.status))?.name ?? statusLabels[ticket.status] ?? ticket.status; }
function resourceTypeLabel(value: string) { return resourceTypes.find((item) => item.value === value)?.label ?? "自定义"; }
function resourceIcon(value: string) { return value === "server" ? RiServerLine : value === "repository" ? RiGitBranchLine : value === "document" ? RiFileTextLine : RiLinkM; }
function resourceSummary(resource: RelatedResource) { const type = resource.resource_type ?? resource.type; const attrs = resource.attributes ?? {}; if (type === "server") return [resource.identifier, attrs.protocol && String(attrs.protocol).toUpperCase(), attrs.port && ":" + attrs.port].filter(Boolean).join(" ") || "未填写连接信息"; if (type === "repository") return [resource.identifier, attrs.provider, attrs.branch && "分支 " + attrs.branch].filter(Boolean).join(" · ") || "未填写仓库信息"; return resource.identifier || resource.description || "未填写资源说明"; }
function ConfirmAction({ title, description, ariaLabel, children, onConfirm, wide = false }: { title: string; description: string; ariaLabel: string; children: ReactNode; onConfirm: () => Promise<void>; wide?: boolean }) { const [open, setOpen] = useState(false); const [busy, setBusy] = useState(false); return <><Button size={wide ? "sm" : "icon-sm"} variant={wide ? "destructive" : "ghost"} aria-label={ariaLabel} onClick={() => setOpen(true)}>{children}</Button><AlertDialog open={open} onOpenChange={(value) => { if (!busy) setOpen(value); }}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>{title}</AlertDialogTitle><AlertDialogDescription>{description}</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel disabled={busy}>取消</AlertDialogCancel><AlertDialogAction disabled={busy} onClick={(event) => { event.preventDefault(); setBusy(true); void onConfirm().then(() => setOpen(false)).finally(() => setBusy(false)); }}>{busy ? "处理中…" : "确认"}</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>; }
function TicketButton({ ticket, router }: { ticket: Ticket; router: Router }) { return <button type="button" className="min-w-0 text-left" onClick={() => void router.push("/modules/workflow-tickets-react/tickets/" + ticket.id)}><span className="block truncate font-medium hover:underline">{ticket.title}</span><span className="block truncate text-xs text-muted-foreground">{ticket.number} · {ticket.workflow_name}</span></button>; }

function ProjectCreateForm({ api, router, onDone }: { api: WorkflowApi; router: Router; onDone?: () => void }) {
  const [name, setName] = useState(""); const [goal, setGoal] = useState(""); const [tags, setTags] = useState(""); const [status, setStatus] = useState("planning"); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  const save = async (event: FormEvent) => { event.preventDefault(); if (!name.trim()) { setError("项目名称不能为空。"); return; } setSaving(true); setError(""); try { const project = await api.createProject({ name: name.trim(), goal: goal.trim(), tags: tags.split(",").map((item) => item.trim()).filter(Boolean), status, planned_start_at: null, target_at: null, default_workflow_id: null, favorite: false }); if (onDone) onDone(); else await router.push("/modules/workflow-tickets-react/projects/" + project.id); } catch (err) { setError(errorMessage(err, "创建项目失败")); } finally { setSaving(false); } };
  return <form className="grid gap-5" onSubmit={save}><FieldGroup><Field><FieldLabel htmlFor="project-name">项目名称</FieldLabel><Input id="project-name" value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：个人知识库整理" autoFocus required /></Field><Field><FieldLabel htmlFor="project-goal">项目目标</FieldLabel><Textarea id="project-goal" value={goal} onChange={(event) => setGoal(event.target.value)} placeholder="这个项目希望达成什么？" rows={4} /></Field><Field><FieldLabel htmlFor="project-tags">标签</FieldLabel><Input id="project-tags" value={tags} onChange={(event) => setTags(event.target.value)} placeholder="例如：学习，长期，个人" /><FieldDescription>多个标签用逗号分隔。</FieldDescription></Field><Field><FieldLabel>项目状态</FieldLabel><Select value={status} onValueChange={(value) => setStatus(value ?? "planning")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>状态</SelectLabel>{projectStatuses.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field></FieldGroup>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={() => onDone?.()}>取消</Button><Button type="submit" disabled={saving}>{saving ? "创建中…" : "创建项目"}</Button></div></form>;
}

function ProjectCard({ project, router }: { project: Project; router: Router }) {
  const goal = project.goal ?? project.description; const completed = project.completed_ticket_count ?? 0; const total = project.ticket_count ?? 0; const currentGoal = project.current_milestone_goal || project.current_milestone_name || "暂无进行中的里程碑";
  const open = () => void router.push("/modules/workflow-tickets-react/projects/" + project.id);
  const dueAt = project.current_milestone_target_at || project.target_at;
  return <div role="button" tabIndex={0} className="group grid cursor-pointer gap-5 rounded-xl border bg-card p-5 text-card-foreground shadow-sm transition-colors hover:border-primary/50 hover:bg-accent/30 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring" onClick={open} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); open(); } }}><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-start gap-3"><span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><RiFlagLine aria-hidden="true" /></span><div className="min-w-0"><h2 className="truncate font-semibold">{project.name}</h2><p className="mt-1 truncate text-xs text-muted-foreground">{project.key}</p></div></div><StatusBadge value={project.status} /></div><p className="min-h-10 text-sm leading-5 text-muted-foreground">{goal || "暂未填写项目目标。"}</p><div className="grid gap-3"><div className="flex items-center justify-between text-sm"><span className="text-muted-foreground">工单进度</span><span className="font-medium">{completed} / {total}</span></div><Progress value={project.progress ?? 0} aria-label={"项目进度 " + (project.progress ?? 0) + "%"} /><div className="flex items-center justify-between gap-3 text-xs text-muted-foreground"><span>里程碑 {project.milestone_count ?? 0} 个</span><span>{project.progress ?? 0}%</span></div></div><div className="grid gap-2 border-t pt-4 text-sm"><span className="text-xs text-muted-foreground">当前里程碑目标</span><span className="truncate">{currentGoal}</span></div><div className="flex items-center justify-between gap-3 border-t pt-4 text-xs text-muted-foreground"><span className="flex min-w-0 items-center gap-1.5"><RiCalendarLine aria-hidden="true" />{dueAt ? formatDate(dueAt) : "未设置里程碑日期"}</span>{project.health && project.health !== "normal" ? <StatusBadge value={project.health} /> : null}</div></div>;
}

export function ProjectsPage({ api, router }: PageProps) {
  const [projects, setProjects] = useState<Project[]>([]); const [keyword, setKeyword] = useState(""); const [status, setStatus] = useState("all"); const [loading, setLoading] = useState(true); const [error, setError] = useState(""); const [createOpen, setCreateOpen] = useState(false);
  const load = async () => { setLoading(true); setError(""); try { setProjects(await api.listProjects()); } catch (err) { setError(errorMessage(err, "项目暂时无法加载")); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const filtered = useMemo(() => { const query = keyword.trim().toLowerCase(); return projects.filter((project) => { const values = [project.name, project.key, project.goal ?? project.description, ...(project.tags ?? [])].join(" ").toLowerCase(); return (!query || values.includes(query)) && (status === "all" || project.status === status); }); }, [keyword, projects, status]);
  return <ProjectFrame><header className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="flex items-center gap-2"><h1 className="text-2xl font-semibold tracking-tight">项目</h1><Button type="button" size="icon-sm" variant="ghost" title="围绕一个个人目标组织工单、里程碑和复盘数据。" aria-label="查看项目说明"><RiInformationLine /></Button></div><Button onClick={() => setCreateOpen(true)}><RiAddLine data-icon="inline-start" />新建项目</Button></header><div className="flex flex-col gap-3 sm:flex-row"><div className="relative min-w-0 flex-1"><RiSearchLine className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" aria-hidden="true" /><Input className="pl-9" value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="搜索项目、目标或标签" aria-label="搜索项目、目标或标签" /></div><div className="flex items-center gap-2"><RiMore2Line className="size-4 text-muted-foreground" aria-hidden="true" /><Select value={status} onValueChange={(value) => setStatus(value ?? "all")}><SelectTrigger className="w-full sm:w-36"><SelectValue placeholder="全部状态" /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>项目状态</SelectLabel><SelectItem value="all">全部状态</SelectItem>{projectStatuses.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></div></div>{error ? <ErrorState message={error} retry={() => void load()} /> : null}{loading ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{Array.from({ length: 4 }, (_, index) => <Card key={index} className="grid gap-4 p-5"><Skeleton className="h-6 w-3/5" /><Skeleton className="h-10 w-full" /><Skeleton className="h-4 w-4/5" /><Skeleton className="h-2 w-full" /></Card>)}</div> : filtered.length ? <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">{filtered.map((project) => <ProjectCard key={project.id} project={project} router={router} />)}</div> : <Card><EmptyState description={projects.length ? "还没有匹配的项目" : "还没有项目，创建一个项目开始组织工单。"} action={<Button onClick={() => setCreateOpen(true)}><RiAddLine data-icon="inline-start" />{projects.length ? "创建项目" : "创建第一个项目"}</Button>} /></Card>}<Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>新建项目</DialogTitle><DialogDescription>围绕一个目标组织工单、里程碑和复盘数据。</DialogDescription></DialogHeader><ProjectCreateForm api={api} router={router} onDone={() => { setCreateOpen(false); void load(); }} /></DialogContent></Dialog></ProjectFrame>;
}

function ProjectEditDialog({ api, project, onSaved }: { api: WorkflowApi; project: Project; onSaved: (project: Project) => void }) {
  const [open, setOpen] = useState(false); const [name, setName] = useState(project.name); const [goal, setGoal] = useState(project.goal ?? project.description); const [status, setStatus] = useState(project.status); const [tags, setTags] = useState((project.tags ?? []).join(", ")); const [note, setNote] = useState(project.note); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  const start = () => { setName(project.name); setGoal(project.goal ?? project.description); setStatus(project.status); setTags((project.tags ?? []).join(", ")); setNote(project.note); setError(""); setOpen(true); };
  const save = async () => { setSaving(true); setError(""); try { const next = await api.updateProject(project.id, { name: name.trim(), goal: goal.trim(), status, tags: tags.split(",").map((item) => item.trim()).filter(Boolean), note }); onSaved(next); setOpen(false); } catch (err) { setError(errorMessage(err, "保存项目失败")); } finally { setSaving(false); } };
  return <><Button variant="outline" onClick={start}><RiEditLine data-icon="inline-start" />编辑项目</Button><Dialog open={open} onOpenChange={setOpen}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>编辑项目</DialogTitle><DialogDescription>更新项目目标、标签、状态和注意事项。</DialogDescription></DialogHeader><FieldGroup><Field><FieldLabel>项目名称</FieldLabel><Input value={name} onChange={(event) => setName(event.target.value)} /></Field><Field><FieldLabel>项目目标</FieldLabel><Textarea value={goal} onChange={(event) => setGoal(event.target.value)} rows={3} /></Field><Field><FieldLabel>标签</FieldLabel><Input value={tags} onChange={(event) => setTags(event.target.value)} /></Field><Field><FieldLabel>项目状态</FieldLabel><Select value={status} onValueChange={(value) => setStatus(value ?? "planning")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>状态</SelectLabel>{projectStatuses.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field><Field><FieldLabel>注意事项</FieldLabel><Textarea value={note} onChange={(event) => setNote(event.target.value)} rows={4} /></Field></FieldGroup>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<DialogFooter><Button variant="outline" onClick={() => setOpen(false)}>取消</Button><Button disabled={saving || !name.trim()} onClick={() => void save()}>{saving ? "保存中…" : "保存项目"}</Button></DialogFooter></DialogContent></Dialog></>;
}

function ProjectHeader({ project, router, api, onSaved, onArchived }: { project: Project; router: Router; api: WorkflowApi; onSaved: (project: Project) => void; onArchived: () => Promise<void> }) {
  return <header className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="flex min-w-0 items-start gap-3"><Button size="icon-sm" variant="ghost" aria-label="返回项目列表" onClick={() => void router.push("/modules/workflow-tickets-react/projects")}><RiArrowLeftLine /></Button><span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><RiFlagLine /></span><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><h1 className="truncate text-2xl font-semibold tracking-tight">{project.name}</h1><HealthBadge value={project.health ?? "normal"} /></div><p className="mt-1 max-w-3xl text-sm text-muted-foreground">{project.goal ?? (project.description || "暂无项目目标")}</p><p className="mt-1 font-mono text-xs text-muted-foreground">{project.key} · 负责人：{project.owner_name || "当前用户"}</p></div></div><div className="flex flex-wrap items-center gap-2 lg:justify-end"><ProjectEditDialog api={api} project={project} onSaved={onSaved} /><ConfirmAction title="归档这个项目？" description="归档后项目默认隐藏，但工单、里程碑和资源都会保留。" ariaLabel="归档项目" onConfirm={onArchived} wide><RiDeleteBinLine data-icon="inline-start" />归档项目</ConfirmAction><Button onClick={() => void router.push("/modules/workflow-tickets-react/tickets/new?project_id=" + project.id)}><RiAddLine data-icon="inline-start" />新建工单</Button></div></header>;
}

function MetricCard({ label, value, hint, progress }: { label: string; value: ReactNode; hint?: string; progress?: number }) { return <Card><CardContent className="grid gap-2 pt-5"><span className="text-sm text-muted-foreground">{label}</span><strong className="text-2xl font-semibold tracking-tight">{value}</strong>{hint ? <span className="text-xs text-muted-foreground">{hint}</span> : null}{progress !== undefined ? <Progress value={progress} aria-label={label + " " + progress + "%"} /> : null}</CardContent></Card>; }

function OverviewTab({ project, milestones, tickets, router, setTab }: { project: Project; milestones: Milestone[]; tickets: Ticket[]; router: Router; setTab: (tab: string) => void }) {
  const recent = [...tickets].sort((a, b) => b.updated_at.localeCompare(a.updated_at)).slice(0, 5); const activeMilestones = milestones.filter((item) => !["completed", "cancelled"].includes(normalizeMilestoneStatus(item.status))).slice(0, 4);
  return <div className="grid gap-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="整体进度" value={(project.progress ?? 0) + "%"} progress={project.progress ?? 0} hint={(project.completed_ticket_count ?? 0) + " / " + (project.ticket_count ?? 0) + " 个工单已完成"} /><MetricCard label="未完成工单" value={Math.max(0, (project.ticket_count ?? tickets.length) - (project.completed_ticket_count ?? 0))} hint="不含已完成和已终止工单" /><MetricCard label="里程碑" value={project.milestone_count ?? milestones.length} hint={milestones.filter((item) => normalizeMilestoneStatus(item.status) === "completed").length + " 个已完成"} /><MetricCard label="当前里程碑" value={<span className="truncate text-lg">{project.current_milestone_name || "暂无"}</span>} hint={formatDate(project.current_milestone_target_at)} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1.25fr)_minmax(18rem,0.75fr)]"><Card><CardHeader className="flex-row items-start justify-between gap-3"><div><CardTitle>近期工单</CardTitle><CardDescription>项目中最近更新的执行任务。</CardDescription></div><Button variant="ghost" size="sm" onClick={() => setTab("tickets")}>查看全部</Button></CardHeader><CardContent>{recent.length ? <div className="grid divide-y">{recent.map((ticket) => <div key={ticket.id} className="flex items-center justify-between gap-4 py-3 first:pt-0 last:pb-0"><div className="flex min-w-0 items-center gap-3"><span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-muted"><RiFileTextLine className="size-4" /></span><TicketButton ticket={ticket} router={router} /></div><div className="flex shrink-0 items-center gap-3"><span className="hidden text-xs text-muted-foreground sm:inline">{formatDate(ticket.updated_at)}</span><StatusBadge value={ticket.status} /></div></div>)}</div> : <EmptyState description="还没有关联工单。" action={<Button size="sm" onClick={() => void router.push("/modules/workflow-tickets-react/tickets/new?project_id=" + project.id)}><RiAddLine data-icon="inline-start" />新建工单</Button>} />}</CardContent></Card><Card><CardHeader className="flex-row items-start justify-between gap-3"><div><CardTitle>里程碑</CardTitle><CardDescription>按阶段查看项目推进情况。</CardDescription></div><Button variant="ghost" size="sm" onClick={() => setTab("milestones")}>查看全部</Button></CardHeader><CardContent>{activeMilestones.length ? <div className="grid divide-y">{activeMilestones.map((milestone) => <button type="button" key={milestone.id} className="grid gap-2 py-3 text-left first:pt-0 last:pb-0 hover:text-primary" onClick={() => void router.push("/modules/workflow-tickets-react/projects/" + project.id + "/milestones/" + milestone.id)}><div className="flex items-center justify-between gap-3"><span className="truncate font-medium">{milestone.name}</span><StatusBadge value={milestone.status} /></div><Progress value={milestone.progress ?? 0} /><span className="text-xs text-muted-foreground">{milestone.progress ?? 0}% · 目标 {formatDate(milestone.target_at)}</span></button>)}</div> : <EmptyState description="暂无进行中的里程碑。" action={<Button size="sm" onClick={() => setTab("milestones")}><RiAddLine data-icon="inline-start" />创建里程碑</Button>} />}</CardContent></Card></div></div>;
}

function TimelineList({ items }: { items: TimelineEvent[] }) { return items.length ? <div className="grid gap-0">{items.map((item) => <div key={item.id} className="relative grid grid-cols-[auto_minmax(0,1fr)] gap-3 pb-5 last:pb-0"><span className="mt-1 flex size-7 items-center justify-center rounded-full bg-muted text-muted-foreground"><RiTimeLine className="size-4" /></span><div className="min-w-0"><p className="font-medium">{timelineLabels[item.type] ?? item.title}</p><p className="mt-1 text-sm text-muted-foreground">{item.detail || item.title}</p><p className="mt-1 text-xs text-muted-foreground">{formatDateTime(item.created_at)} · {item.actor_name}</p></div></div>)}</div> : <EmptyState description="暂无动态。" />; }

function TicketsTab({ api, tickets, router }: { api: WorkflowApi; tickets: Ticket[]; router: Router }) {
  const [selectedId, setSelectedId] = useState(tickets.find((ticket) => !["completed", "cancelled", "archived"].includes(ticket.status))?.id ?? tickets[0]?.id ?? ""); const [timeline, setTimeline] = useState<TimelineEvent[]>([]); const [loading, setLoading] = useState(false);
  useEffect(() => { if (!selectedId) { setTimeline([]); return; } setLoading(true); void api.getTimeline({ ticket_id: selectedId }).then(setTimeline).catch(() => setTimeline([])).finally(() => setLoading(false)); }, [api, selectedId]);
  return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(20rem,0.65fr)]"><Card><CardHeader><CardTitle>项目工单</CardTitle><CardDescription>选择工单查看执行进度和动态。</CardDescription></CardHeader><CardContent>{tickets.length ? <div className="grid divide-y">{tickets.map((ticket) => <div key={ticket.id} className={"grid gap-2 py-4 first:pt-0 last:pb-0 " + (selectedId === ticket.id ? "text-primary" : "")} role="button" tabIndex={0} aria-selected={selectedId === ticket.id} onClick={() => setSelectedId(ticket.id)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setSelectedId(ticket.id); } }}><div className="flex items-center justify-between gap-3"><span className="min-w-0 truncate font-medium">{ticket.title}</span><div className="flex shrink-0 items-center gap-2"><StatusBadge value={ticket.status} /><Button size="sm" variant="ghost" onClick={(event) => { event.stopPropagation(); void router.push("/modules/workflow-tickets-react/tickets/" + ticket.id); }}>进入工单<RiExternalLinkLine data-icon="inline-end" /></Button></div></div><div className="flex items-center gap-3 text-xs text-muted-foreground"><span>{ticket.number}</span><span>{currentTicketNode(ticket)}</span><span className="ml-auto">{ticketProgress(ticket)}%</span></div><Progress value={ticketProgress(ticket)} /></div>)}</div> : <EmptyState description="暂无关联工单。" />}</CardContent></Card><Card><CardHeader><CardTitle>工单动态</CardTitle><CardDescription>{tickets.find((item) => item.id === selectedId)?.title ?? "选择一个工单"}</CardDescription></CardHeader><CardContent>{loading ? <LoadingState /> : <TimelineList items={timeline} />}</CardContent></Card></div>;
}

function MilestoneFormDialog({ api, projectId, milestone, open, onOpenChange, onSaved }: { api: WorkflowApi; projectId: string; milestone: Milestone | undefined; open: boolean; onOpenChange: (open: boolean) => void; onSaved: () => Promise<void> }) {
  const [draft, setDraft] = useState<MilestoneDraft>({ name: "", goal: "", target_at: "", status: "pending", completion_criteria: "", risk_note: "", review_markdown: "", progress_mode: "ticket_count", manual_progress: "0", owner_name: "" }); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!open) return; setDraft({ name: milestone?.name ?? "", goal: milestone?.goal ?? milestone?.description ?? "", target_at: dateInput(milestone?.target_at), status: normalizeMilestoneStatus(milestone?.status ?? "pending"), completion_criteria: milestone?.completion_criteria ?? "", risk_note: milestone?.risk_note ?? "", review_markdown: milestone?.review_markdown ?? milestone?.review ?? "", progress_mode: milestone?.progress_mode === "manual" ? "manual" : "ticket_count", manual_progress: String(milestone?.manual_progress ?? milestone?.progress ?? 0), owner_name: milestone?.owner_name ?? "" }); setError(""); }, [milestone, open]);
  const update = (key: keyof MilestoneDraft, value: string) => setDraft((current) => ({ ...current, [key]: value }));
  const save = async (event: FormEvent) => { event.preventDefault(); if (!draft.name.trim()) { setError("里程碑名称不能为空。"); return; } setSaving(true); setError(""); try { const payload = { name: draft.name.trim(), goal: draft.goal.trim(), target_at: toIso(draft.target_at), status: draft.status, completion_criteria: draft.completion_criteria, risk_note: draft.risk_note, review_markdown: draft.review_markdown, progress_mode: draft.progress_mode, manual_progress: Number(draft.manual_progress) || 0, owner_name: draft.owner_name }; if (milestone) await api.updateMilestone(projectId, milestone.id, payload); else await api.createMilestone(projectId, payload); await onSaved(); onOpenChange(false); } catch (err) { setError(errorMessage(err, milestone ? "保存里程碑失败" : "创建里程碑失败")); } finally { setSaving(false); } };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle>{milestone ? "编辑里程碑" : "新建里程碑"}</DialogTitle><DialogDescription>用阶段目标、完成标准和复盘记录推动项目进展。</DialogDescription></DialogHeader><form className="grid gap-5" onSubmit={save}><FieldGroup><Field><FieldLabel>里程碑名称</FieldLabel><Input value={draft.name} onChange={(event) => update("name", event.target.value)} autoFocus /></Field><Field><FieldLabel>阶段目标</FieldLabel><Textarea value={draft.goal} onChange={(event) => update("goal", event.target.value)} rows={3} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>目标日期</FieldLabel><Input type="date" value={draft.target_at} onChange={(event) => update("target_at", event.target.value)} /></Field><Field><FieldLabel>状态</FieldLabel><Select value={draft.status} onValueChange={(value) => update("status", value ?? "pending")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>状态</SelectLabel>{milestoneStatuses.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field></div><Field><FieldLabel>负责人</FieldLabel><Input value={draft.owner_name} onChange={(event) => update("owner_name", event.target.value)} placeholder="默认当前用户" /></Field><Field><FieldLabel>完成标准</FieldLabel><Textarea value={draft.completion_criteria} onChange={(event) => update("completion_criteria", event.target.value)} rows={2} /></Field><Field><FieldLabel>风险说明</FieldLabel><Textarea value={draft.risk_note} onChange={(event) => update("risk_note", event.target.value)} rows={2} /></Field><div className="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>进度计算</FieldLabel><Select value={draft.progress_mode} onValueChange={(value) => update("progress_mode", value ?? "ticket_count")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>计算方式</SelectLabel>{milestoneModes.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field>{draft.progress_mode === "manual" ? <Field><FieldLabel>手动进度（%）</FieldLabel><Input type="number" min="0" max="100" value={draft.manual_progress} onChange={(event) => update("manual_progress", event.target.value)} /></Field> : null}</div><Field><FieldLabel>里程碑复盘</FieldLabel><Textarea value={draft.review_markdown} onChange={(event) => update("review_markdown", event.target.value)} rows={5} placeholder={"# 阶段结果\n\n记录完成情况和经验。"} /></Field></FieldGroup>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>取消</Button><Button type="submit" disabled={saving}>{saving ? "保存中…" : milestone ? "保存修改" : "创建里程碑"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function MilestonesTab({ api, projectId, milestones, tickets, router, reload }: { api: WorkflowApi; projectId: string; milestones: Milestone[]; tickets: Ticket[]; router: Router; reload: () => Promise<void> }) {
  const [open, setOpen] = useState(false); const [editing, setEditing] = useState<Milestone>(); const [expanded, setExpanded] = useState<Set<string>>(new Set(milestones.filter((item) => !["completed", "cancelled"].includes(normalizeMilestoneStatus(item.status))).map((item) => item.id)));
  useEffect(() => { setExpanded(new Set(milestones.filter((item) => !["completed", "cancelled"].includes(normalizeMilestoneStatus(item.status))).map((item) => item.id))); }, [milestones]);
  const edit = (milestone?: Milestone) => { setEditing(milestone); setOpen(true); }; const toggle = (id: string) => setExpanded((current) => { const next = new Set(current); if (next.has(id)) next.delete(id); else next.add(id); return next; });
  return <div className="grid gap-4"><Card><CardHeader className="flex-row items-center justify-between gap-3"><div><CardTitle>里程碑</CardTitle><CardDescription>阶段目标、进度、风险和复盘都集中在这里。</CardDescription></div><Button onClick={() => edit()}><RiAddLine data-icon="inline-start" />新建里程碑</Button></CardHeader><CardContent>{milestones.length ? <div className="grid gap-3">{milestones.map((milestone) => { const linked = tickets.filter((ticket) => ticket.milestone_id === milestone.id); const isOpen = expanded.has(milestone.id); return <div key={milestone.id} className="rounded-lg border"><div className="flex items-start gap-3 p-4"><Button size="icon-sm" variant="ghost" aria-label={isOpen ? "收起里程碑" : "展开里程碑"} onClick={() => toggle(milestone.id)}><RiMore2Line className={isOpen ? "rotate-90 transition-transform" : "transition-transform"} /></Button><button type="button" className="min-w-0 flex-1 text-left" onClick={() => toggle(milestone.id)}><div className="flex flex-wrap items-center gap-2"><span className="truncate font-medium">{milestone.name}</span><StatusBadge value={milestone.status} /></div><p className="mt-1 line-clamp-2 text-sm text-muted-foreground">{milestone.goal ?? milestone.description ?? "暂未填写阶段目标。"}</p></button><div className="flex shrink-0 items-center gap-1"><Button size="icon-sm" variant="ghost" aria-label="编辑里程碑" onClick={() => edit(milestone)}><RiEditLine /></Button><ConfirmAction title="删除这个里程碑？" description="删除后，关联工单会解除里程碑关联。" ariaLabel="删除里程碑" onConfirm={async () => { await api.deleteMilestone(projectId, milestone.id); await reload(); }}><RiDeleteBinLine /></ConfirmAction></div></div><div className="grid gap-2 px-16 pb-4"><div className="flex items-center gap-3"><Progress value={milestone.progress ?? 0} /><span className="shrink-0 text-xs text-muted-foreground">{milestone.progress ?? 0}%</span></div><div className="flex flex-wrap gap-x-5 gap-y-1 text-xs text-muted-foreground"><span>{milestone.completed_ticket_count ?? 0} / {milestone.ticket_count ?? linked.length} 个工单完成</span><span>目标 {formatDate(milestone.target_at)}</span><span>负责人 {milestone.owner_name || "当前用户"}</span></div></div>{isOpen ? <div className="grid gap-4 border-t bg-muted/20 px-16 py-4"><div className="grid gap-2"><h3 className="text-sm font-medium">关联工单</h3>{linked.length ? linked.map((ticket) => <div key={ticket.id} className="flex items-center justify-between gap-3 rounded-md bg-background p-3"><div className="flex min-w-0 items-center gap-2"><RiFileTextLine className="size-4 shrink-0 text-muted-foreground" /><TicketButton ticket={ticket} router={router} /></div><span className="text-xs text-muted-foreground">{ticketProgress(ticket)}%</span></div>) : <p className="text-sm text-muted-foreground">暂无关联工单。</p>}</div><div className="grid gap-4 sm:grid-cols-2"><div><span className="text-xs text-muted-foreground">完成标准</span><p className="mt-1 whitespace-pre-wrap text-sm">{milestone.completion_criteria || "未填写"}</p></div><div><span className="text-xs text-muted-foreground">风险说明</span><p className="mt-1 whitespace-pre-wrap text-sm">{milestone.risk_note || "未填写"}</p></div></div><div><span className="text-xs text-muted-foreground">里程碑复盘</span>{milestone.review_markdown || milestone.review ? <article className="tn-workflow-tickets-markdown-preview mt-2" dangerouslySetInnerHTML={markdownHtml(milestone.review_markdown ?? milestone.review)} /> : <p className="mt-1 text-sm text-muted-foreground">还没有复盘记录。</p>}</div><div className="flex justify-end"><Button size="sm" variant="outline" onClick={() => void router.push("/modules/workflow-tickets-react/projects/" + projectId + "/milestones/" + milestone.id)}>查看里程碑详情</Button></div></div> : null}</div>; })}</div> : <EmptyState description="还没有里程碑，创建第一个阶段开始推进项目。" action={<Button onClick={() => edit()}><RiAddLine data-icon="inline-start" />创建里程碑</Button>} />}</CardContent></Card><MilestoneFormDialog api={api} projectId={projectId} milestone={editing} open={open} onOpenChange={setOpen} onSaved={reload} /></div>;
}

function ResourceFormDialog({ api, projectId, tickets, milestones, editing, open, onOpenChange, onSaved }: { api: WorkflowApi; projectId: string; tickets: Ticket[]; milestones: Milestone[]; editing: RelatedResource | undefined; open: boolean; onOpenChange: (open: boolean) => void; onSaved: () => Promise<void> }) {
  const [draft, setDraft] = useState<ResourceDraft>({ name: "", resource_type: "custom", identifier: "", external_url: "", description: "", protocol: "ssh", port: "", provider: "github", branch: "main", document_type: "online", ticket_ids: [], milestone_ids: [] }); const [error, setError] = useState(""); const [saving, setSaving] = useState(false);
  useEffect(() => { if (!open) return; const attrs = editing?.attributes ?? {}; const type = editing?.resource_type ?? editing?.type ?? "custom"; setDraft({ name: editing?.name ?? "", resource_type: type, identifier: editing?.identifier ?? "", external_url: editing?.external_url ?? editing?.url ?? "", description: editing?.description ?? "", protocol: String(attrs.protocol ?? "ssh"), port: String(attrs.port ?? ""), provider: String(attrs.provider ?? "github"), branch: String(attrs.branch ?? "main"), document_type: String(attrs.document_type ?? "online"), ticket_ids: editing?.ticket_ids ?? [], milestone_ids: editing?.milestone_ids ?? [] }); setError(""); }, [editing, open]);
  const update = (key: keyof ResourceDraft, value: string | string[]) => setDraft((current) => ({ ...current, [key]: value })); const toggleId = (key: "ticket_ids" | "milestone_ids", id: string) => setDraft((current) => ({ ...current, [key]: current[key].includes(id) ? current[key].filter((item) => item !== id) : [...current[key], id] }));
  const save = async (event: FormEvent) => { event.preventDefault(); if (!draft.name.trim()) { setError("资源名称不能为空。"); return; } setSaving(true); setError(""); const attributes = draft.resource_type === "server" ? { protocol: draft.protocol, port: draft.port } : draft.resource_type === "repository" ? { provider: draft.provider, branch: draft.branch } : draft.resource_type === "document" ? { document_type: draft.document_type } : {}; try { const payload = { project_id: projectId, name: draft.name.trim(), type: draft.resource_type, resource_type: draft.resource_type, identifier: draft.identifier.trim(), url: draft.external_url.trim() || null, external_url: draft.external_url.trim() || null, description: draft.description, attributes, ticket_ids: draft.ticket_ids, milestone_ids: draft.milestone_ids }; if (editing) await api.updateResource(editing.id, payload); else await api.createResource(payload); await onSaved(); onOpenChange(false); } catch (err) { setError(errorMessage(err, editing ? "保存资源失败" : "创建资源失败")); } finally { setSaving(false); } };
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="sm:max-w-2xl"><DialogHeader><DialogTitle>{editing ? "编辑关联资源" : "关联资源"}</DialogTitle><DialogDescription>保存项目相关的服务器、代码仓库、文档或自定义链接。</DialogDescription></DialogHeader><form className="grid gap-5" onSubmit={save}><FieldGroup><div className="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>资源名称</FieldLabel><Input value={draft.name} onChange={(event) => update("name", event.target.value)} autoFocus /></Field><Field><FieldLabel>资源类型</FieldLabel><Select value={draft.resource_type} onValueChange={(value) => update("resource_type", value ?? "custom")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>类型</SelectLabel>{resourceTypes.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field></div><Field><FieldLabel>{draft.resource_type === "server" ? "主机地址" : draft.resource_type === "repository" ? "仓库地址" : draft.resource_type === "document" ? "文档标识" : "资源标识"}</FieldLabel><Input value={draft.identifier} onChange={(event) => update("identifier", event.target.value)} placeholder="例如：repo/toolnest" /></Field>{draft.resource_type === "server" ? <div className="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>协议</FieldLabel><Select value={draft.protocol} onValueChange={(value) => update("protocol", value ?? "ssh")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>协议</SelectLabel>{["ssh", "http", "https", "other"].map((value) => <SelectItem key={value} value={value}>{value.toUpperCase()}</SelectItem>)}</SelectGroup></SelectContent></Select></Field><Field><FieldLabel>端口</FieldLabel><Input value={draft.port} onChange={(event) => update("port", event.target.value)} placeholder="22" /></Field></div> : null}{draft.resource_type === "repository" ? <div className="grid gap-4 sm:grid-cols-2"><Field><FieldLabel>平台</FieldLabel><Select value={draft.provider} onValueChange={(value) => update("provider", value ?? "github")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>平台</SelectLabel>{["github", "gitlab", "self_hosted", "other"].map((value) => <SelectItem key={value} value={value}>{value === "self_hosted" ? "自建平台" : value[0]?.toUpperCase() + value.slice(1)}</SelectItem>)}</SelectGroup></SelectContent></Select></Field><Field><FieldLabel>分支</FieldLabel><Input value={draft.branch} onChange={(event) => update("branch", event.target.value)} /></Field></div> : null}{draft.resource_type === "document" ? <Field><FieldLabel>文档类型</FieldLabel><Select value={draft.document_type} onValueChange={(value) => update("document_type", value ?? "online")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>类型</SelectLabel>{[["online", "在线文档"], ["knowledge_base", "知识库"], ["design", "设计文档"], ["other", "其他"]].map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field> : null}<Field><FieldLabel>外部链接</FieldLabel><Input type="url" value={draft.external_url} onChange={(event) => update("external_url", event.target.value)} placeholder="https://" /></Field><Field><FieldLabel>描述</FieldLabel><Textarea value={draft.description} onChange={(event) => update("description", event.target.value)} rows={3} /></Field><div className="grid gap-3 sm:grid-cols-2"><Field><FieldLabel>关联工单</FieldLabel><div className="grid max-h-40 gap-2 overflow-y-auto rounded-md border p-3">{tickets.length ? tickets.map((ticket) => <label key={ticket.id} className="flex items-start gap-2 text-sm"><Checkbox checked={draft.ticket_ids.includes(ticket.id)} onCheckedChange={() => toggleId("ticket_ids", ticket.id)} /><span className="min-w-0 truncate">{ticket.title}</span></label>) : <span className="text-sm text-muted-foreground">暂无工单</span>}</div></Field><Field><FieldLabel>关联里程碑</FieldLabel><div className="grid max-h-40 gap-2 overflow-y-auto rounded-md border p-3">{milestones.length ? milestones.map((milestone) => <label key={milestone.id} className="flex items-start gap-2 text-sm"><Checkbox checked={draft.milestone_ids.includes(milestone.id)} onCheckedChange={() => toggleId("milestone_ids", milestone.id)} /><span className="min-w-0 truncate">{milestone.name}</span></label>) : <span className="text-sm text-muted-foreground">暂无里程碑</span>}</div></Field></div></FieldGroup>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<DialogFooter><Button type="button" variant="outline" onClick={() => onOpenChange(false)}>取消</Button><Button type="submit" disabled={saving}>{saving ? "保存中…" : editing ? "保存修改" : "关联资源"}</Button></DialogFooter></form></DialogContent></Dialog>;
}

function ResourceDetailDialog({ resource, tickets, milestones, open, onOpenChange, router }: { resource: RelatedResource | undefined; tickets: Ticket[]; milestones: Milestone[]; open: boolean; onOpenChange: (open: boolean) => void; router: Router }) {
  if (!resource) return null; const Icon = resourceIcon(resource.resource_type ?? resource.type); const linkedTickets = tickets.filter((ticket) => resource.ticket_ids?.includes(ticket.id)); const linkedMilestones = milestones.filter((milestone) => resource.milestone_ids?.includes(milestone.id));
  return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="sm:max-w-xl"><DialogHeader><div className="flex items-center gap-3"><span className="flex size-9 items-center justify-center rounded-lg bg-muted"><Icon className="size-5" /></span><div><DialogTitle>{resource.name}</DialogTitle><DialogDescription>{resourceTypeLabel(resource.resource_type ?? resource.type)} · {resourceSummary(resource)}</DialogDescription></div></div></DialogHeader><div className="grid gap-5"><div className="grid gap-1"><span className="text-xs text-muted-foreground">描述</span><p className="whitespace-pre-wrap text-sm">{resource.description || "未填写描述。"}</p></div>{resource.url || resource.external_url ? <a className="flex items-center gap-2 text-sm text-primary hover:underline" href={resource.url ?? resource.external_url ?? "#"} target="_blank" rel="noreferrer"><RiExternalLinkLine />打开外部链接</a> : null}<div className="grid gap-2 sm:grid-cols-2"><div><span className="text-xs text-muted-foreground">关联工单</span>{linkedTickets.length ? <div className="mt-2 grid gap-2">{linkedTickets.map((ticket) => <TicketButton key={ticket.id} ticket={ticket} router={router} />)}</div> : <p className="mt-1 text-sm text-muted-foreground">暂无</p>}</div><div><span className="text-xs text-muted-foreground">关联里程碑</span>{linkedMilestones.length ? <div className="mt-2 grid gap-2">{linkedMilestones.map((milestone) => <button type="button" className="block truncate text-left text-sm hover:text-primary hover:underline" key={milestone.id} onClick={() => void router.push("/modules/workflow-tickets-react/projects/" + milestone.project_id + "/milestones/" + milestone.id)}>{milestone.name}</button>)}</div> : <p className="mt-1 text-sm text-muted-foreground">暂无</p>}</div></div><p className="text-xs text-muted-foreground">最近更新：{formatDateTime(resource.updated_at)}</p></div></DialogContent></Dialog>;
}

function ResourcesTab({ api, projectId, resources, tickets, milestones, reload, router }: { api: WorkflowApi; projectId: string; resources: RelatedResource[]; tickets: Ticket[]; milestones: Milestone[]; reload: () => Promise<void>; router: Router }) {
  const [keyword, setKeyword] = useState(""); const [type, setType] = useState("all"); const [open, setOpen] = useState(false); const [editing, setEditing] = useState<RelatedResource>(); const [details, setDetails] = useState<RelatedResource>();
  const filtered = useMemo(() => { const query = keyword.trim().toLowerCase(); return resources.filter((resource) => { const resourceType = resource.resource_type ?? resource.type; return (!query || [resource.name, resource.identifier, resource.description, resourceSummary(resource)].join(" ").toLowerCase().includes(query)) && (type === "all" || resourceType === type); }); }, [keyword, resources, type]); const edit = (resource?: RelatedResource) => { setEditing(resource); setOpen(true); };
  return <div className="grid gap-4"><Card><CardHeader className="flex-row items-start justify-between gap-3"><div><CardTitle>关联资源</CardTitle><CardDescription>服务器、代码仓库、文档和项目上下文。</CardDescription></div><Button onClick={() => edit()}><RiAddLine data-icon="inline-start" />关联资源</Button></CardHeader><CardContent className="grid gap-4"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative min-w-0 flex-1"><RiSearchLine className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" aria-hidden="true" /><Input className="pl-9" value={keyword} onChange={(event) => setKeyword(event.target.value)} placeholder="搜索资源名称、标识或描述" aria-label="搜索资源" /></div><Select value={type} onValueChange={(value) => setType(value ?? "all")}><SelectTrigger className="w-full sm:w-40"><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>资源类型</SelectLabel><SelectItem value="all">全部资源</SelectItem>{resourceTypes.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></div>{filtered.length ? <div className="grid gap-3 md:grid-cols-2">{filtered.map((resource) => { const Icon = resourceIcon(resource.resource_type ?? resource.type); return <div key={resource.id} className="grid gap-4 rounded-lg border p-4"><button type="button" className="flex min-w-0 items-start gap-3 text-left" onClick={() => setDetails(resource)}><span className="flex size-9 shrink-0 items-center justify-center rounded-lg bg-muted"><Icon className="size-5" /></span><span className="min-w-0"><strong className="block truncate">{resource.name}</strong><span className="mt-1 block truncate text-xs text-muted-foreground">{resourceTypeLabel(resource.resource_type ?? resource.type)} · {resourceSummary(resource)}</span></span></button><p className="line-clamp-2 min-h-10 text-sm text-muted-foreground">{resource.description || "未填写描述。"}</p><div className="flex items-center justify-between gap-3 border-t pt-3 text-xs text-muted-foreground"><span>{resource.ticket_ids?.length ?? 0} 个工单 · {resource.milestone_ids?.length ?? 0} 个里程碑</span><div className="flex items-center gap-1"><Button size="icon-sm" variant="ghost" aria-label="编辑资源" onClick={() => edit(resource)}><RiEditLine /></Button><ConfirmAction title="删除这个关联资源？" description="删除后资源将从项目上下文中移除。" ariaLabel="删除资源" onConfirm={async () => { await api.deleteResource(resource.id); await reload(); }}><RiDeleteBinLine /></ConfirmAction></div></div></div>; })}</div> : <EmptyState description={resources.length ? "还没有匹配的资源。" : "暂未关联资源。"} action={<Button onClick={() => edit()}><RiAddLine data-icon="inline-start" />关联第一个资源</Button>} />}</CardContent></Card><ResourceFormDialog api={api} projectId={projectId} tickets={tickets} milestones={milestones} editing={editing} open={open} onOpenChange={setOpen} onSaved={reload} /><ResourceDetailDialog resource={details} tickets={tickets} milestones={milestones} open={Boolean(details)} onOpenChange={(value) => { if (!value) setDetails(undefined); }} router={router} /></div>;
}

function AnalyticsTab({ analytics }: { analytics: Record<string, unknown> }) {
  const duration = (analytics.duration_hours && typeof analytics.duration_hours === "object" ? analytics.duration_hours : {}) as Record<string, unknown>;
  const trend = Array.isArray(analytics.trend) ? analytics.trend as Array<Record<string, unknown>> : [];
  const nodeDurations = Array.isArray(analytics.node_durations) ? analytics.node_durations as Array<Record<string, unknown>> : [];
  const paths = Array.isArray(analytics.path_distribution) ? analytics.path_distribution as Array<Record<string, unknown>> : [];
  const max = Math.max(1, ...trend.map((item) => Math.max(Number(item.created) || 0, Number(item.completed) || 0)));
  const maxNodeDuration = Math.max(1, ...nodeDurations.map((item) => Number(item.hours) || 0));
  return <div className="grid gap-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="日均完成" value={Number(analytics.daily_velocity || 0).toFixed(1)} hint="近 14 天" /><MetricCard label="阻塞工单" value={Number(analytics.blocked_count) || 0} /><MetricCard label="逾期工单" value={Number(analytics.overdue_count) || 0} /><MetricCard label="平均耗时" value={Number(duration.average || 0).toFixed(1) + " 小时"} hint={"中位数 " + Number(duration.median || 0).toFixed(1) + " 小时"} /></div><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(18rem,0.65fr)]"><Card><CardHeader><CardTitle>工单趋势</CardTitle><CardDescription>近 14 天创建与完成的工单数量。</CardDescription></CardHeader><CardContent>{trend.length ? <div className="grid gap-3">{trend.map((item) => <div className="grid grid-cols-[5rem_minmax(0,1fr)_auto] items-center gap-3 text-sm" key={String(item.date)}><span className="text-xs text-muted-foreground">{String(item.date).slice(5)}</span><div className="grid gap-1"><Progress value={(Number(item.created) || 0) / max * 100} aria-label={String(item.date) + " 创建"} /><Progress value={(Number(item.completed) || 0) / max * 100} aria-label={String(item.date) + " 完成"} /></div><span className="text-xs text-muted-foreground">{Number(item.created) || 0} / {Number(item.completed) || 0}</span></div>)}</div> : <EmptyState description="暂无趋势数据。" />}</CardContent></Card><Card><CardHeader><CardTitle>状态分布</CardTitle><CardDescription>当前项目工单状态。</CardDescription></CardHeader><CardContent className="grid gap-3">{countEntries(analytics.status_counts).length ? countEntries(analytics.status_counts).map(([status, count]) => <div className="flex items-center justify-between gap-3 text-sm" key={status}><span>{statusLabels[status] ?? status}</span><Badge variant="outline">{count}</Badge></div>) : <EmptyState description="暂无工单分析数据。" />}</CardContent></Card></div><div className="grid gap-5 lg:grid-cols-2"><Card><CardHeader><CardTitle>节点耗时</CardTitle><CardDescription>识别流程中最可能形成瓶颈的节点。</CardDescription></CardHeader><CardContent>{nodeDurations.length ? <div className="grid gap-4">{nodeDurations.map((item) => <div className="grid gap-2" key={String(item.name)}><div className="flex items-center justify-between gap-3 text-sm"><span className="truncate font-medium">{String(item.name)}</span><span className="shrink-0 text-xs text-muted-foreground">{Number(item.hours) || 0} 小时 · {Number(item.count) || 0} 次</span></div><Progress value={(Number(item.hours) || 0) / maxNodeDuration * 100} aria-label={String(item.name) + " 节点耗时"} /></div>)}</div> : <EmptyState description="完成更多节点后显示耗时分析。" />}</CardContent></Card><Card><CardHeader><CardTitle>常见流转路径</CardTitle><CardDescription>按实际完成节点序列聚合，而非模板节点顺序。</CardDescription></CardHeader><CardContent className="grid gap-3">{paths.length ? paths.map((item) => <div className="flex items-center justify-between gap-3 rounded-md border px-3 py-2 text-sm" key={String(item.path)}><span className="min-w-0 truncate">{String(item.path)}</span><Badge variant="outline">{Number(item.count) || 0} 次</Badge></div>) : <EmptyState description="暂无完整流转路径。" />}</CardContent></Card></div></div>;
}

function ActivityTab({ timeline }: { timeline: TimelineEvent[] }) { return <Card><CardHeader><CardTitle>项目动态</CardTitle><CardDescription>记录项目、里程碑、资源和工单的重要变化。</CardDescription></CardHeader><CardContent><TimelineList items={timeline} /></CardContent></Card>; }

function NotesTab({ api, project, onSaved }: { api: WorkflowApi; project: Project; onSaved: (project: Project) => void }) {
  const [draft, setDraft] = useState(project.review_markdown ?? project.note ?? ""); const [editing, setEditing] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  useEffect(() => { setDraft(project.review_markdown ?? project.note ?? ""); }, [project]);
  const save = async () => { setSaving(true); setError(""); try { onSaved(await api.updateProject(project.id, { review_markdown: draft })); setEditing(false); } catch (err) { setError(errorMessage(err, "保存注意事项失败")); } finally { setSaving(false); } };
  return <Card><CardHeader className="flex-row items-start justify-between gap-3"><div><CardTitle>注意事项</CardTitle><CardDescription>支持 Markdown，用于记录项目复盘、约束和后续行动。</CardDescription></div>{editing ? <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => { setDraft(project.review_markdown ?? project.note ?? ""); setEditing(false); }}>取消</Button><Button size="sm" disabled={saving} onClick={() => void save()}><RiSaveLine data-icon="inline-start" />{saving ? "保存中…" : "保存"}</Button></div> : <Button size="sm" onClick={() => setEditing(true)}><RiEditLine data-icon="inline-start" />编辑注意事项</Button>}</CardHeader><CardContent>{editing ? <Textarea value={draft} onChange={(event) => setDraft(event.target.value)} rows={14} placeholder={"# 项目复盘\n\n记录值得保留的经验。"} /> : draft.trim() ? <article className="tn-workflow-tickets-markdown-preview" dangerouslySetInnerHTML={markdownHtml(draft)} /> : <EmptyState description="还没有注意事项。" action={<Button size="sm" onClick={() => setEditing(true)}>添加注意事项</Button>} />}{error ? <Alert variant="destructive" className="mt-4"><AlertDescription>{error}</AlertDescription></Alert> : null}</CardContent></Card>;
}

function SettingsTab({ api, project, onSaved, onArchived }: { api: WorkflowApi; project: Project; onSaved: (project: Project) => void; onArchived: () => Promise<void> }) {
  const [name, setName] = useState(project.name); const [goal, setGoal] = useState(project.goal ?? project.description); const [status, setStatus] = useState(project.status); const [tags, setTags] = useState((project.tags ?? []).join(", ")); const [favorite, setFavorite] = useState(Boolean(project.favorite)); const [saving, setSaving] = useState(false); const [error, setError] = useState("");
  useEffect(() => { setName(project.name); setGoal(project.goal ?? project.description); setStatus(project.status); setTags((project.tags ?? []).join(", ")); setFavorite(Boolean(project.favorite)); }, [project]);
  const save = async () => { setSaving(true); setError(""); try { onSaved(await api.updateProject(project.id, { name, goal, status, tags: tags.split(",").map((item) => item.trim()).filter(Boolean), favorite })); } catch (err) { setError(errorMessage(err, "保存项目设置失败")); } finally { setSaving(false); } };
  return <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(18rem,0.7fr)]"><Card><CardHeader><CardTitle>基本设置</CardTitle><CardDescription>更新项目基本信息和个人偏好。</CardDescription></CardHeader><CardContent className="grid gap-5"><FieldGroup><Field><FieldLabel>项目名称</FieldLabel><Input value={name} onChange={(event) => setName(event.target.value)} /></Field><Field><FieldLabel>项目目标</FieldLabel><Textarea value={goal} onChange={(event) => setGoal(event.target.value)} rows={4} /></Field><Field><FieldLabel>项目状态</FieldLabel><Select value={status} onValueChange={(value) => setStatus(value ?? "planning")}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectGroup><SelectLabel>状态</SelectLabel>{projectStatuses.map((item) => <SelectItem key={item.value} value={item.value}>{item.label}</SelectItem>)}</SelectGroup></SelectContent></Select></Field><Field><FieldLabel>标签</FieldLabel><Input value={tags} onChange={(event) => setTags(event.target.value)} /></Field><Field orientation="horizontal"><Switch checked={favorite} onCheckedChange={setFavorite} /><div><FieldLabel>收藏项目</FieldLabel><FieldDescription>收藏状态用于后续项目筛选和排序。</FieldDescription></div></Field></FieldGroup>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}</CardContent><CardFooter><Button disabled={saving || !name.trim()} onClick={() => void save()}><RiSaveLine data-icon="inline-start" />{saving ? "保存中…" : "保存设置"}</Button></CardFooter></Card><div className="grid content-start gap-5"><Card><CardHeader><CardTitle>项目信息</CardTitle><CardDescription>由系统维护的只读信息。</CardDescription></CardHeader><CardContent className="grid gap-3 text-sm"><div className="flex justify-between gap-3"><span className="text-muted-foreground">项目编号</span><span className="font-mono">{project.key}</span></div><div className="flex justify-between gap-3"><span className="text-muted-foreground">负责人</span><span>{project.owner_name || "当前用户"}</span></div><div className="flex justify-between gap-3"><span className="text-muted-foreground">创建时间</span><span>{formatDateTime(project.created_at)}</span></div><div className="flex justify-between gap-3"><span className="text-muted-foreground">最近更新</span><span>{formatDateTime(project.updated_at)}</span></div></CardContent></Card><Card><CardHeader><CardTitle>项目组成</CardTitle><CardDescription>计划和执行由下方对象共同维护。</CardDescription></CardHeader><CardContent className="grid gap-4"><div className="flex items-start gap-3"><RiFileTextLine className="mt-0.5 size-5 shrink-0 text-muted-foreground" /><div><p className="font-medium">任意工单组合</p><p className="mt-1 text-sm text-muted-foreground">工单可按需要加入项目，不绑定单一模板。</p></div></div><div className="flex items-start gap-3"><RiCalendarLine className="mt-0.5 size-5 shrink-0 text-muted-foreground" /><div><p className="font-medium">里程碑控制计划</p><p className="mt-1 text-sm text-muted-foreground">阶段目标、日期和复盘在各自里程碑中维护。</p></div></div><div className="flex items-start gap-3"><RiLinkM className="mt-0.5 size-5 shrink-0 text-muted-foreground" /><div><p className="font-medium">资源独立关联</p><p className="mt-1 text-sm text-muted-foreground">服务器、仓库、文档等资源按实际范围关联。</p></div></div></CardContent></Card><Card className="border-destructive/40"><CardHeader><CardTitle>危险操作</CardTitle><CardDescription>归档项目不会删除关联数据。</CardDescription></CardHeader><CardContent><ConfirmAction title="归档这个项目？" description="项目归档后将从默认列表中隐藏，关联工单、里程碑和资源会保留。" ariaLabel="归档项目" onConfirm={onArchived} wide><RiDeleteBinLine data-icon="inline-start" />归档项目</ConfirmAction></CardContent></Card></div></div>;
}

export function ProjectDetailPage({ api, router, params, query }: PageProps) {
  const projectId = requiredParam(params.projectId || params.id, "项目"); const [project, setProject] = useState<Project>(); const [milestones, setMilestones] = useState<Milestone[]>([]); const [tickets, setTickets] = useState<Ticket[]>([]); const [resources, setResources] = useState<RelatedResource[]>([]); const [analytics, setAnalytics] = useState<Record<string, unknown>>({}); const [timeline, setTimeline] = useState<TimelineEvent[]>([]); const [tab, setTab] = useState(String(query.tab || "overview") === "review" ? "notes" : String(query.tab || "overview")); const [loading, setLoading] = useState(true); const [error, setError] = useState("");
  const load = async () => { setLoading(true); setError(""); try { const [nextProject, nextMilestones, ticketPage, nextResources, nextAnalytics, nextTimeline] = await Promise.all([api.getProject(projectId), api.listMilestones(projectId), api.listTickets({ project_id: projectId }), api.listResources({ project_id: projectId }), api.getProjectAnalytics(projectId), api.getTimeline({ project_id: projectId })]); setProject(nextProject); setMilestones(nextMilestones); setTickets(ticketPage.items); setResources(nextResources); setAnalytics(nextAnalytics); setTimeline(nextTimeline); } catch (err) { setError(errorMessage(err, "项目详情加载失败")); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, [projectId]);
  if (loading && !project) return <ProjectFrame><LoadingState /></ProjectFrame>; if (error && !project) return <ProjectFrame><ErrorState message={error} retry={() => void load()} /></ProjectFrame>; if (!project) return null;
  const switchTab = (value: string) => { setTab(value); void router.push("/modules/workflow-tickets-react/projects/" + projectId + (value === "overview" ? "" : "?tab=" + value)); }; const archived = async () => { await api.archiveProject(project.id); await router.push("/modules/workflow-tickets-react/projects"); }; const updateProject = (next: Project) => setProject(next);
  return <ProjectFrame><ProjectHeader project={project} router={router} api={api} onSaved={updateProject} onArchived={archived} />{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<Tabs value={tab} onValueChange={switchTab}><TabsList className="h-auto w-full justify-start gap-1 overflow-x-auto"><TabsTrigger value="overview"><RiFlagLine data-icon="inline-start" />概览</TabsTrigger><TabsTrigger value="tickets"><RiFileTextLine data-icon="inline-start" />工单</TabsTrigger><TabsTrigger value="milestones"><RiCalendarLine data-icon="inline-start" />里程碑</TabsTrigger><TabsTrigger value="analysis"><RiBarChartLine data-icon="inline-start" />分析</TabsTrigger><TabsTrigger value="activity"><RiTimeLine data-icon="inline-start" />动态</TabsTrigger><TabsTrigger value="resources"><RiLinkM data-icon="inline-start" />资源</TabsTrigger><TabsTrigger value="notes"><RiFileTextLine data-icon="inline-start" />注意事项</TabsTrigger><TabsTrigger value="settings"><RiSettings3Line data-icon="inline-start" />设置</TabsTrigger></TabsList><TabsContent value="overview"><OverviewTab project={project} milestones={milestones} tickets={tickets} router={router} setTab={switchTab} /></TabsContent><TabsContent value="tickets"><TicketsTab api={api} tickets={tickets} router={router} /></TabsContent><TabsContent value="milestones"><MilestonesTab api={api} projectId={project.id} milestones={milestones} tickets={tickets} router={router} reload={load} /></TabsContent><TabsContent value="analysis"><AnalyticsTab analytics={analytics} /></TabsContent><TabsContent value="activity"><ActivityTab timeline={timeline} /></TabsContent><TabsContent value="resources"><ResourcesTab api={api} projectId={project.id} resources={resources} tickets={tickets} milestones={milestones} reload={load} router={router} /></TabsContent><TabsContent value="notes"><NotesTab api={api} project={project} onSaved={updateProject} /></TabsContent><TabsContent value="settings"><SettingsTab api={api} project={project} onSaved={updateProject} onArchived={archived} /></TabsContent></Tabs></ProjectFrame>;
}

export function ProjectCreatePage({ api, router }: PageProps) { return <ProjectFrame><header className="flex items-center gap-3"><Button size="icon-sm" variant="ghost" aria-label="返回项目列表" onClick={() => void router.push("/modules/workflow-tickets-react/projects")}><RiArrowLeftLine /></Button><div><h1 className="text-2xl font-semibold tracking-tight">新建项目</h1><p className="mt-1 text-sm text-muted-foreground">为一组关联工单建立协作上下文。</p></div></header><Card><CardContent className="pt-5"><ProjectCreateForm api={api} router={router} /></CardContent></Card></ProjectFrame>; }

export function MilestoneDetailPage({ api, router, params }: PageProps) {
  const projectId = requiredParam(params.projectId, "项目"); const milestoneId = requiredParam(params.milestoneId, "里程碑"); const [project, setProject] = useState<Project>(); const [milestone, setMilestone] = useState<Milestone>(); const [tickets, setTickets] = useState<Ticket[]>([]); const [resources, setResources] = useState<RelatedResource[]>([]); const [timeline, setTimeline] = useState<TimelineEvent[]>([]); const [open, setOpen] = useState(false); const [error, setError] = useState("");
  const load = async () => { setError(""); try { const [nextProject, nextMilestone, ticketPage, nextResources, nextTimeline] = await Promise.all([api.getProject(projectId), api.getMilestone(projectId, milestoneId), api.listTickets({ milestone_id: milestoneId }), api.listResources({ project_id: projectId, milestone_id: milestoneId }), api.getTimeline({ project_id: projectId, milestone_id: milestoneId })]); setProject(nextProject); setMilestone(nextMilestone); setTickets(ticketPage.items); setResources(nextResources); setTimeline(nextTimeline); } catch (err) { setError(errorMessage(err, "里程碑详情加载失败")); } };
  useEffect(() => { void load(); }, [projectId, milestoneId]); if (error && !milestone) return <ProjectFrame><ErrorState message={error} retry={() => void load()} /></ProjectFrame>; if (!project || !milestone) return <ProjectFrame><LoadingState /></ProjectFrame>; const activeCount = tickets.filter((ticket) => !["completed", "cancelled", "archived"].includes(ticket.status)).length;
  return <ProjectFrame><header className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="flex min-w-0 items-start gap-3"><Button size="icon-sm" variant="ghost" aria-label="返回项目里程碑" onClick={() => void router.push("/modules/workflow-tickets-react/projects/" + projectId + "?tab=milestones")}><RiArrowLeftLine /></Button><span className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-primary/10 text-primary"><RiCalendarLine /></span><div className="min-w-0"><p className="text-sm text-muted-foreground"><button type="button" className="hover:text-primary hover:underline" onClick={() => void router.push("/modules/workflow-tickets-react/projects/" + projectId)}>{project.name}</button> / 里程碑详情</p><div className="mt-1 flex flex-wrap items-center gap-2"><h1 className="truncate text-2xl font-semibold tracking-tight">{milestone.name}</h1><StatusBadge value={milestone.status} /></div></div></div><Button onClick={() => setOpen(true)}><RiEditLine data-icon="inline-start" />编辑里程碑</Button></header>{error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : null}<div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="阶段进度" value={(milestone.progress ?? 0) + "%"} progress={milestone.progress ?? 0} /><MetricCard label="关联工单" value={milestone.ticket_count ?? tickets.length} hint={activeCount + " 个待处理"} /><MetricCard label="完成情况" value={(milestone.completed_ticket_count ?? 0) + " / " + (milestone.ticket_count ?? tickets.length)} hint={milestone.progress_mode === "manual" ? "手动设置" : "按工单数量"} /><MetricCard label="目标日期" value={<span className="text-lg">{formatDate(milestone.target_at)}</span>} hint={"负责人：" + (milestone.owner_name || "当前用户")} /></div><div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(18rem,0.65fr)]"><main className="grid gap-5"><Card><CardHeader><CardTitle>阶段目标</CardTitle><CardDescription>里程碑用于组织一组工单，项目计划由阶段逐步推进。</CardDescription></CardHeader><CardContent className="grid gap-4"><p className="whitespace-pre-wrap text-sm leading-6">{milestone.goal ?? milestone.description ?? "暂未填写阶段目标。"}</p><div className="grid gap-4 sm:grid-cols-2"><div><span className="text-xs text-muted-foreground">完成标准</span><p className="mt-1 whitespace-pre-wrap text-sm">{milestone.completion_criteria || "未填写"}</p></div><div><span className="text-xs text-muted-foreground">风险说明</span><p className="mt-1 whitespace-pre-wrap text-sm">{milestone.risk_note || "未填写"}</p></div></div></CardContent></Card><Card><CardHeader><CardTitle>关联工单</CardTitle><CardDescription>当前阶段内的执行任务和完成进度。</CardDescription></CardHeader><CardContent>{tickets.length ? <div className="grid divide-y">{tickets.map((ticket) => <div key={ticket.id} className="flex items-center justify-between gap-4 py-4 first:pt-0 last:pb-0"><div className="flex min-w-0 items-center gap-3"><span className="flex size-8 shrink-0 items-center justify-center rounded-md bg-muted"><RiFileTextLine className="size-4" /></span><TicketButton ticket={ticket} router={router} /></div><div className="flex shrink-0 items-center gap-3"><div className="hidden w-24 gap-1 sm:grid"><Progress value={ticketProgress(ticket)} /><span className="text-right text-xs text-muted-foreground">{ticketProgress(ticket)}%</span></div><StatusBadge value={ticket.status} /></div></div>)}</div> : <EmptyState description="还没有关联工单。" />}</CardContent></Card><Card><CardHeader><CardTitle>里程碑复盘</CardTitle><CardDescription>支持 Markdown，记录阶段结果、偏差和后续行动。</CardDescription></CardHeader><CardContent>{milestone.review_markdown || milestone.review ? <article className="tn-workflow-tickets-markdown-preview" dangerouslySetInnerHTML={markdownHtml(milestone.review_markdown ?? milestone.review)} /> : <EmptyState description="还没有复盘记录。" action={<Button onClick={() => setOpen(true)}><RiEditLine data-icon="inline-start" />添加复盘</Button>} />}</CardContent></Card></main><aside className="grid content-start gap-5"><Card><CardHeader><CardTitle>里程碑动态</CardTitle><CardDescription>记录当前阶段的重要变化。</CardDescription></CardHeader><CardContent><TimelineList items={timeline} /></CardContent></Card><Card><CardHeader><CardTitle>关联资源</CardTitle><CardDescription>当前阶段可使用的项目资源。</CardDescription></CardHeader><CardContent>{resources.length ? <div className="grid gap-3">{resources.map((resource) => <div key={resource.id} className="flex items-center gap-3"><RiLinkM className="size-4 shrink-0 text-muted-foreground" /><span className="truncate text-sm">{resource.name}</span></div>)}</div> : <EmptyState description="暂未关联资源。" />}</CardContent></Card></aside></div><MilestoneFormDialog api={api} projectId={projectId} milestone={milestone} open={open} onOpenChange={setOpen} onSaved={load} /></ProjectFrame>;
}
